const sqlUnknown = () => "SQL_DIAG_REPORT UNKNOWN\n";
const sqlHash = (text) => createHash("sha256").update(text).digest("hex");
const sqlDynamicPrefix = 'rejects rich/authority keys inside the old patch atomically: {"primaryTitle":"Known field must not make unknown keys acceptable","operation":{"type":"TITLE_REMOVE","titleId":"';
const sqlDynamicSuffix = '"}}';
function sqlIdentity(file, test) {
  let title = test.title;
  if (file.id === "F030" && title.startsWith(sqlDynamicPrefix) && title.endsWith(sqlDynamicSuffix)) {
    const uuid = title.slice(sqlDynamicPrefix.length, -sqlDynamicSuffix.length);
    if (/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(uuid))
      title = sqlDynamicPrefix + "00000000-0000-4000-8000-000000000000" + sqlDynamicSuffix;
  }
  return sqlHash(JSON.stringify([test.ancestorTitles, title]));
}
function sqlSite(messages, file, target) {
  // Only AssertionError-shaped frames with the exact absolute or fixed full
  // repository-relative atlas path; no path normalization or suffix matching.
  // Filename suffixes, URIs, traversal and arbitrary prefixes never qualify.
  if (!messages.some((s) => /^AssertionError:/m.test(s))) return "UNKNOWN";
  const hits = new Set();
  for (const message of messages.filter((s) => /^AssertionError:/m.test(s))) for (const row of message.split("\n")) {
    const frame = /^\s*(?:at (?:[A-Za-z_$][\w.$<>]* \()?|❯ )(.+):(\d+):(\d+)\)?\s*$/.exec(row);
    if (!frame || (frame[1] !== target && frame[1] !== file.path)) continue;
    const line = Number(frame[2]), column = Number(frame[3]);
    if (!Number.isSafeInteger(line) || !Number.isSafeInteger(column) || column < 1) continue;
    const matches = file.sites.flatMap(([start, end, col, endCol], i) =>
      line >= start && line <= end && (line !== start || column >= col) &&
      (line !== end || column <= endCol) ? [i] : []);
    if (matches.length !== 1) return "UNKNOWN";
    hits.add(matches[0]);
  }
  return hits.size === 1 ? `A${String([...hits][0] + 1).padStart(3, "0")}` : "UNKNOWN";
}

export function summarizeSqlFailures(report, exitCode, root = process.cwd()) {
  try {
    if (!Number.isInteger(exitCode) || exitCode < 0 || exitCode > 255 ||
        !report || typeof report.success !== "boolean" ||
        !Array.isArray(report.testResults) || report.testResults.length !== 40)
      return sqlUnknown();
    const counts = countKeys.map((key) => report[key]);
    if (!counts.every((n) => Number.isSafeInteger(n) && n >= 0 && n <= 386)) return sqlUnknown();
    const [total, passed, failed, pending, todo] = counts;
    if (total !== 386 || total !== passed + failed + pending + todo) return sqlUnknown();
    // Optional JSON reporter suite counters must form a consistent bounded tuple.
    const suiteKeys = ["numTotalTestSuites", "numPassedTestSuites", "numFailedTestSuites", "numPendingTestSuites"];
    if (suiteKeys.some((key) => key in report)) {
      const [all, pass, fail, wait] = suiteKeys.map((key) => report[key]);
      if (![all, pass, fail, wait].every((n) => Number.isSafeInteger(n) && n >= 0 && n <= 426) ||
          all !== pass + fail + wait || all !== 79 || (report.success && fail) || (!report.success && !fail)) return sqlUnknown();
    }
    const expected = new Map(sqlAtlas.map((f) => [resolve(root, f.path), f]));
    const seenFiles = new Set(), rows = [], failures = [];
    let hasFileFailure = false;
    for (const file of report.testResults) {
      if (!file || typeof file.name !== "string" || !isAbsolute(file.name) ||
          !expected.has(file.name) || seenFiles.has(file.name) ||
          !["passed", "failed"].includes(file.status) || typeof file.message !== "string" ||
          !Array.isArray(file.assertionResults)) return sqlUnknown();
      seenFiles.add(file.name);
      const fixed = expected.get(file.name);
      if (sqlHash(readFileSync(file.name, "utf8")) !== fixed.sourceHash ||
          file.assertionResults.length !== fixed.hashes.length) return sqlUnknown();
      const seen = new Set();
      let fileFailed = false;
      for (const test of file.assertionResults) {
        if (!test || typeof test.title !== "string" || !Array.isArray(test.ancestorTitles) ||
            !test.ancestorTitles.every((s) => typeof s === "string") || !states.has(test.status) ||
            !Array.isArray(test.failureMessages) || !test.failureMessages.every((s) => typeof s === "string") ||
            (test.status !== "failed" && test.failureMessages.length)) return sqlUnknown();
        const ordinal = fixed.hashes.indexOf(sqlIdentity(fixed, test));
        if (ordinal < 0 || seen.has(ordinal)) return sqlUnknown();
        seen.add(ordinal); rows.push(test.status);
        if (test.status === "failed") {
          fileFailed = true;
          failures.push({ file: fixed.id, ordinal: ordinal + 1,
            category: category(test.failureMessages), site: sqlSite(test.failureMessages, fixed, file.name) });
        }
      }
      const hook = file.message.length > 0 || (file.status === "failed" && !fileFailed);
      if ((fileFailed || hook) && file.status !== "failed") return sqlUnknown();
      if (file.status === "failed") hasFileFailure = true;
      if (hook) failures.push({file: fixed.id, ordinal: 0, category: "SUITE_OR_HOOK_FAILURE", site: "UNKNOWN"});
    }
    if (rows.filter((s) => s === "passed").length !== passed ||
        rows.filter((s) => s === "failed").length !== failed ||
        rows.filter((s) => s === "pending" || s === "skipped").length !== pending ||
        rows.filter((s) => s === "todo").length !== todo ||
        report.success !== (!failed && !hasFileFailure) ||
        (exitCode === 0) !== report.success) return sqlUnknown();
    if (failures.length > 386) return sqlUnknown();
    // COMPLETE describes fingerprint coverage, never a test PASS or process exit.
    failures.sort((a, b) => a.file.localeCompare(b.file) || a.ordinal - b.ordinal);
    return ["SQL_DIAG_REPORT COMPLETE", `SQL_DIAG_COUNTS FILES 40 CASES 386 FAILED ${failed}`,
      ...failures.map((f) => `SQL_DIAG_FAIL ${f.file} C${String(f.ordinal).padStart(3, "0")} CATEGORY ${f.category} SITE ${f.site}`)
    ].join("\n") + "\n";
  } catch {
    return sqlUnknown();
  }
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(resolve(process.argv[1])).href
) {
  let receipt;
  const sqlDiagnostics = process.argv[4] === "--sql-fingerprints";
  try {
    const report = JSON.parse(readFileSync(process.argv[2], "utf8"));
    receipt = summarize(report, Number(process.argv[3]));
    if (sqlDiagnostics) receipt += summarizeSqlFailures(report, Number(process.argv[3]));
  } catch {
    receipt = unknown();
    if (sqlDiagnostics) receipt += sqlUnknown();
  }
  process.stdout.write(receipt);
}
